inline constexpr const Recipe* find(std::string_view deviceClass, std::string_view gyroMatrixId, std::string_view accelMatrixId) noexcept {
    for (const auto& recipe : recipes)
        if (recipe.deviceClass == deviceClass && recipe.gyroMatrixId == gyroMatrixId && recipe.accelMatrixId == accelMatrixId) return &recipe;
    return nullptr;
}
inline constexpr bool containsClass(std::string_view deviceClass) noexcept {
    for (const auto& recipe : recipes) if (recipe.deviceClass == deviceClass) return true;
    return false;
}
